<template>
  <main class="review-page">
    <header class="review-heading"><div><h1>代码审查</h1><p>从 AI 初审到人工确认，集中处理团队代码中的候选问题。</p></div><div class="page-actions"><button class="btn-secondary" @click="load" :disabled="loading"><WorkbenchIcon name="refresh" :size="16" :class="{ 'is-spinning': loading }" />{{ loading ? '刷新中…' : '刷新任务' }}</button><button class="btn-primary" @click="showScan = true"><WorkbenchIcon name="code" :size="17" />全项目扫描</button></div></header>
    <CodeReviewScanDialog v-if="showScan" @close="showScan = false" @created="scanCreated" />
    <ReviewRepositorySetup v-if="showSetup" @close="showSetup = false; load()" />
    <ReviewEnvironmentPanel v-if="showEnvironment" @close="showEnvironment = false" />
    <div class="repository-readiness-bar" :class="{ warning: unreadyCount > 0 }"><span>{{ readinessLoaded ? `仓库检查：${repositories.length - unreadyCount} / ${repositories.length} 已就绪` : '正在读取仓库检查状态…' }}<small v-if="unreadyCount">{{ unreadyCount }} 个仓库需配置或启动执行端，暂不可发起审查</small></span><div class="repository-readiness-actions"><button class="btn-secondary" @click="showEnvironment = true">环境与同步</button><button class="btn-secondary" @click="showSetup = true">仓库设置</button></div></div>
    <p v-if="error" role="alert" class="review-error">{{ error }}</p>
    <section class="review-overview" aria-label="当前已加载任务概况">
      <button :class="{ selected: view === 'all' }" :aria-pressed="view === 'all'" @click="view = 'all'"><span>全部审查任务</span><strong>{{ tasks.length }}</strong><small>当前已加载</small></button>
      <button :class="{ selected: view === 'pending' }" :aria-pressed="view === 'pending'" @click="view = 'pending'"><span>待人工复核</span><strong>{{ summary.pending }}<em v-if="summary.issues">{{ summary.issues }} 项候选问题</em></strong><small>AI 已返回，等待你确认</small></button>
      <button :class="{ selected: view === 'running' }" :aria-pressed="view === 'running'" @click="view = 'running'"><span>执行中 / 排队</span><strong>{{ summary.running }}</strong><small>由本机执行端处理</small></button>
      <button :class="{ selected: view === 'failed' }" :aria-pressed="view === 'failed'" @click="view = 'failed'"><span>需要重新处理</span><strong>{{ summary.failed }}</strong><small>执行失败或已中断</small></button>
    </section>
    <div class="review-content-card">
      <div class="review-list-heading"><div><h2>审查任务</h2><span>{{ filtered.length }} 条结果</span></div><span class="executor-indicator"><i :class="{ online }" />{{ online ? '本机执行端在线' : '等待执行端上线' }}</span></div>
      <div class="review-filters"><label class="review-search"><WorkbenchIcon name="search" :size="17" /><input v-model="search" aria-label="搜索成员、仓库或提交" placeholder="搜索提交、成员或仓库" /></label><select v-model="kind" aria-label="审查方式"><option value="">全部审查方式</option><option value="commit">提交审查</option><option value="scan">全项目扫描</option></select><select v-model="status" aria-label="执行状态"><option value="">全部执行状态</option><option v-for="(label, key) in states" :key="key" :value="key">{{ label }}</option></select><button v-if="view !== 'all' || search || status || kind" class="clear-review-filter" @click="resetFilters">清除筛选</button></div>
      <div v-if="!tasks.length && !loading" class="review-empty"><WorkbenchIcon name="code" :size="32" /><h2>从一次提交审查开始</h2><p>选择成员提交检查新增问题，或发起全项目扫描。</p><router-link class="btn-primary" to="/dashboard/daily-activity">选择成员提交</router-link></div>
      <div v-else class="review-table-wrap"><table class="review-table"><thead><tr><th>审查任务</th><th>仓库 / 成员</th><th>执行状态</th><th>候选问题</th><th>人工复核</th><th>提交时间</th><th>创建时间</th><th aria-label="操作"></th></tr></thead><tbody>
        <tr v-for="task in filtered" :key="task.name"><td><router-link class="task-title" :to="`/dashboard/code-review/${task.name}`">{{ task.title || task.head_sha.slice(0, 8) }}</router-link><div class="task-meta"><span class="task-kind">{{ task.review_mode === 'scan' ? '全项目扫描' : '提交审查' }}</span><code>{{ task.head_sha.slice(0, 8) }}</code><span v-if="task.branch">{{ task.branch }}</span></div></td>
        <td><span class="task-repository" :title="task.repository">{{ task.repository }}</span><small class="task-member">{{ task.review_mode === 'scan' ? '项目完整文件' : task.member_name || '未归属成员' }}</small></td>
        <td><span :class="['review-badge', task.status]">{{ states[task.status] || task.status }}</span></td>
        <td><span :class="['pending-issue-count', { 'has-issues': task.pending_count > 0 }]">{{ task.pending_count }} 待确认</span><small class="confirmed-issue-count">{{ task.confirmed_count }} 已确认</small></td><td><span :class="['human-review-state', { done: task.review_status === 'completed' }]">{{ reviewStates[task.review_status] }}</span></td><td class="task-date"><template v-if="task.committed_at">{{ task.committed_at.slice(0, 10) }}<small>{{ task.committed_at.slice(11, 16) }}</small></template><span v-else>—</span></td><td class="task-date">{{ task.creation?.slice(0, 10) }}<small>{{ task.creation?.slice(11, 16) }}</small></td><td><router-link class="review-row-action" :to="`/dashboard/code-review/${task.name}`">{{ ['completed', 'partial'].includes(task.status) && task.review_status !== 'completed' ? '去复核' : '查看' }}<WorkbenchIcon name="arrow" :size="15" /></router-link></td></tr>
        <tr v-if="loading && !tasks.length"><td colspan="8" class="table-state">正在读取审查任务…</td></tr><tr v-else-if="!filtered.length"><td colspan="8" class="table-state">没有匹配的审查任务。<button class="clear-review-filter" @click="resetFilters">重置筛选</button></td></tr>
      </tbody></table></div>
      <footer class="review-list-footer"><WorkbenchIcon name="shield" :size="15" /><span>审查结果仅在工作台保留，由你复核后线下反馈。</span><router-link to="/dashboard/daily-activity">从成员提交发起审查</router-link></footer>
    </div>
    <details class="runner-help"><summary>执行端设置与连接说明</summary><p>本机执行器连接第三方模型完成只读审查。预检通过后领取任务，保持终端开启。</p><p>在执行器目录运行：<code>.\start-review-runner.ps1</code>。配置与诊断见 <code>tools/review_runner/README.md</code>。</p></details>
  </main>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import CodeReviewScanDialog from '@/components/CodeReviewScanDialog.vue'
import ReviewRepositorySetup from '@/components/ReviewRepositorySetup.vue'
import ReviewEnvironmentPanel from '@/components/ReviewEnvironmentPanel.vue'
import WorkbenchIcon from '@/components/WorkbenchIcon.vue'
import { reviewApi, states, reviewStates } from '@/utils/codeReview'
import { reviewSummary, matchesReviewView } from '@/utils/reviewPresentation'
const router = useRouter(), showScan = ref(false)
const showSetup = ref(false), showEnvironment = ref(false), repositories = ref([]), readinessLoaded = ref(false)
const unreadyCount = computed(() => repositories.value.filter(r => r.readiness.status !== 'ready').length)
function scanCreated(name) { showScan.value = false; router.push(`/dashboard/code-review/${name}`) }
const tasks = ref([]), executors = ref([]), error = ref(''), loading = ref(false), search = ref(''), status = ref(''), kind = ref(''), view = ref('all')
let timer, alive = true
const online = computed(() => executors.value.some(e => e.last_seen && Date.now() - Date.parse(e.last_seen.replace(' ', 'T') + '+08:00') < 90000))
const summary = computed(() => reviewSummary(tasks.value))
const filtered = computed(() => tasks.value.filter(t => matchesReviewView(t, view.value) && (!status.value || t.status === status.value) && (!kind.value || (t.review_mode || 'commit') === kind.value) && `${t.title} ${t.repository} ${t.member_name} ${t.head_sha}`.toLowerCase().includes(search.value.trim().toLowerCase())))
function resetFilters() { view.value = 'all'; search.value = ''; status.value = ''; kind.value = '' }
async function load() {
  if (loading.value) return
  loading.value = true
  try { const [result, readiness] = await Promise.all([reviewApi('list_tasks'), reviewApi('repository_readiness')]); if (alive) { tasks.value = result.tasks; executors.value = result.executors; repositories.value = readiness; readinessLoaded.value = true; error.value = '' } }
  catch (e) { if (alive) error.value = e.message } finally { if (alive) loading.value = false }
}
onMounted(() => { load(); timer = setInterval(load, 10000) })
onUnmounted(() => { alive = false; clearInterval(timer) })
</script>

